def stable_toposort(graph):
    # Validate and build structures
    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"Missing dependency: {dep}")

    in_degree = {node: len(deps) for node, deps in graph.items()}
    dependents = {node: [] for node in graph}
    for node, deps in graph.items():
        for dep in deps:
            dependents[dep].append(node)

    ready = {node for node, deg in in_degree.items() if deg == 0}
    order = []
    original_order = list(graph.keys())

    while ready:
        # Find the first node in original insertion order that is ready
        for node in original_order:
            if node in ready:
                break
        else:
            # Should never happen because ready is non-empty
            raise ValueError("No ready node found")

        ready.remove(node)
        order.append(node)

        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                ready.add(dependent)

    if len(order) != len(graph):
        raise ValueError("Cycle detected in graph")

    return order
