def schema_drift(expected, actual):
    differences = []

    def collect_leaf_paths(value, prefix):
        paths = []
        if isinstance(value, dict):
            for key, val in value.items():
                new_prefix = f"{prefix}.{key}" if prefix else key
                paths.extend(collect_leaf_paths(val, new_prefix))
        else:
            paths.append(prefix)
        return paths

    def compare(e, a, path):
        # Both are dicts -> recurse
        if isinstance(e, dict) and isinstance(a, dict):
            keys = set(e.keys()) | set(a.keys())
            for key in sorted(keys):
                new_path = f"{path}.{key}" if path else key
                if key in e and key in a:
                    compare(e[key], a[key], new_path)
                elif key in e:  # missing in actual
                    differences.extend(collect_leaf_paths(e[key], new_path))
                else:           # extra in actual
                    differences.extend(collect_leaf_paths(a[key], new_path))
        else:
            # One is dict, other is not -> type mismatch
            # Both are leaf strings and differ -> type mismatch
            if e != a:
                differences.append(path)

    compare(expected, actual, "")
    return sorted(differences)
