def merge_payload_ranges(items):
    # Validate all items
    for start, end, payload in items:
        if start > end:
            raise ValueError("start > end")

    # Sort by start, then end
    sorted_items = sorted(items, key=lambda x: (x[0], x[1]))

    result = []
    for start, end, payload in sorted_items:
        if not result:
            result.append([start, end, payload])
        else:
            last = result[-1]
            if last[2] == payload and last[1] >= start:
                # Merge: extend the end to the maximum
                last[1] = max(last[1], end)
            else:
                result.append([start, end, payload])

    return result
